parameters.command:
cat > /tmp/plan.json << 'PLAN'
{
  "ops": [
    {
      "op": "add-variable",
      "id": "invoiceId",
      "direction": "in",
      "type": "string",
      "description": "Invoice identifier passed to the flow"
    },
    {
      "op": "add-variable",
      "id": "invoiceAmount",
      "direction": "in",
      "type": "number",
      "description": "Invoice amount in currency units"
    },
    {
      "op": "add-variable",
      "id": "reviewDecision",
      "direction": "out",
      "type": "string",
      "description": "Outcome selected by the finance manager: Approve or Reject"
    },
    {
      "op": "add-node",
      "id": "invoiceReview",
      "type": "uipath.human-in-the-loop.quick-form",
      "typeVersion": "1.0",
      "definitionFile": "/tmp/hitl_def.json",
      "label": "Finance Manager Review",
      "inputs": {
        "title": "Invoice Approval Request",
        "priority": "Medium",
        "schema": {
          "schemaId": "1aadacc3-52d2-47c3-9fd1-46979db7711e",
          "fields": [
            {
              "id": "invoiceId",
              "label": "Invoice ID",
              "type": "text",
              "direction": "input",
              "binding": "vars.start.output.invoiceId"
            },
            {
              "id": "amount",
              "label": "Amount",
              "type": "number",
              "direction": "input",
              "binding": "vars.start.output.invoiceAmount"
            }
          ],
          "outcomes": [
            {
              "id": "approve",
              "name": "Approve",
              "type": "string",
              "isPrimary": true,
              "action": "Continue"
            },
            {
              "id": "reject",
              "name": "Reject",
              "type": "string",
              "isPrimary": false,
              "action": "End"
            }
          ]
        },
        "recipient": {
          "channels": ["Email", "ActionCenter"],
          "connections": {},
          "assignee": { "type": "group" }
        }
      }
    },
    {
      "op": "add-node",
      "id": "endNode",
      "type": "core.control.end",
      "typeVersion": "1.0",
      "definitionFile": "/tmp/end_def.json",
      "label": "End",
      "outputs": "none"
    },
    {
      "op": "add-edge",
      "source": "start",
      "sourcePort": "output",
      "target": "invoiceReview",
      "targetPort": "input"
    },
    {
      "op": "add-edge",
      "source": "invoiceReview",
      "sourcePort": "completed",
      "target": "endNode",
      "targetPort": "input"
    },
    {
      "op": "add-output-mapping",
      "endNode": "endNode",
      "var": "reviewDecision",
      "source": "=js:$vars.invoiceReview.status"
    }
  ]
}
PLAN
